import Customers from './pages/Customers';
import CustomerDashboard from './pages/CustomerDashboard';
import Invoices from './pages/Invoices';
import Calendar from './pages/Calendar';

function App() {
  const [isExpanded, setIsExpanded] = useState(false);

  return (
    <Router>
      <div className="bg-background-light dark:bg-background-dark font-display text-gray-800 dark:text-gray-200 h-screen flex p-4 transition-colors duration-200">
        <Sidebar isExpanded={isExpanded} setIsExpanded={setIsExpanded} />
        <main id="main-content" className={`flex-1 transition-all duration-300 ease-in-out overflow-x-hidden flex flex-col ${isExpanded ? 'ml-[17rem]' : 'ml-24'}`}>
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/customers" element={<Customers />} />
            <Route path="/customers/:customerId" element={<CustomerDashboard />} />
            <Route path="/invoices" element={<Invoices />} />
            <Route path="/calendar" element={<Calendar />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App;
